use serde::{Deserialize,Serialize};use serde_json::{Map,Value};use sha2::{Digest,Sha256};use std::collections::{BTreeMap,BTreeSet};
#[derive(Deserialize)]pub struct FieldSchema{pub path:String,pub kind:String,#[serde(default)]pub required:bool,#[serde(default)]pub nullable:bool}
#[derive(Deserialize)]pub struct DataProcessRequest{pub records:Vec<Value>,#[serde(default)]pub baseline_records:Vec<Value>,#[serde(default)]pub dedupe_keys:Vec<String>,#[serde(default)]pub index_fields:Vec<String>,#[serde(default)]pub required_fields:Vec<String>,#[serde(default)]pub schema:Vec<FieldSchema>,#[serde(default)]pub trim_strings:bool,#[serde(default)]pub lowercase_keys:bool,#[serde(default)]pub normalize_numbers:bool,#[serde(default)]pub normalize_booleans:bool,#[serde(default)]pub normalize_dates:bool,#[serde(default)]pub duplicate_policy:String,#[serde(default)]pub chunk_size:usize,#[serde(default)]pub memory_limit_bytes:usize,#[serde(default)]pub cancel_after_rows:Option<usize>,#[serde(default)]pub sqlite_columns:Vec<String>}
#[derive(Serialize)]pub struct DataIssue{pub code:&'static str,pub row:usize,pub field:Option<String>,pub detail:String}
#[derive(Serialize)]pub struct DataDiff{pub added:usize,pub removed:usize,pub unchanged:usize,pub added_hashes:Vec<String>,pub removed_hashes:Vec<String>}
#[derive(Serialize)]pub struct DataEvidence{pub contract_version:u32,pub canonical_sha256:String,pub issue_count:usize,pub schema_valid:bool,pub sqlite_ready:bool,pub processed_chunks:usize}
#[derive(Serialize)]pub struct DataProcessResult{pub records:Vec<Value>,pub input_count:usize,pub output_count:usize,pub duplicate_count:usize,pub invalid_count:usize,pub indexes:BTreeMap<String,BTreeMap<String,Vec<usize>>>,pub canonical_sha256:String,pub issues:Vec<DataIssue>,pub diff:DataDiff,pub evidence:DataEvidence,pub estimated_bytes:usize,pub cancelled:bool,pub engine:&'static str,pub owner_domain:&'static str,pub receipt_version:u32}
fn path_value<'a>(v:&'a Value,path:&str)->Option<&'a Value>{let mut current=v;for part in path.split('.'){current=current.get(part)?;}Some(current)}
fn parse_scalar(text:&str,n:bool,b:bool,d:bool)->Value{let t=text.trim();if b{if t.eq_ignore_ascii_case("true")||t=="1"{return Value::Bool(true)}if t.eq_ignore_ascii_case("false")||t=="0"{return Value::Bool(false)}}if n{if let Ok(i)=t.parse::<i64>(){return Value::Number(i.into())}if let Ok(f)=t.parse::<f64>(){if let Some(v)=serde_json::Number::from_f64(f){return Value::Number(v)}}}if d&&t.len()>=10{let bytes=t.as_bytes();if bytes.get(4)==Some(&b'-')&&bytes.get(7)==Some(&b'-'){return Value::String(t[..10].to_string())}}Value::String(t.to_string())}
fn normalize(v:Value,r:&DataProcessRequest)->Value{match v{Value::String(s)=>{let s=if r.trim_strings{s.trim().to_string()}else{s};parse_scalar(&s,r.normalize_numbers,r.normalize_booleans,r.normalize_dates)},Value::Array(a)=>Value::Array(a.into_iter().map(|v|normalize(v,r)).collect()),Value::Object(o)=>{let mut sorted=BTreeMap::new();for(k,v)in o{let key=if r.lowercase_keys{k.trim().to_ascii_lowercase()}else{k.trim().to_string()};sorted.insert(key,normalize(v,r));}Value::Object(sorted.into_iter().collect::<Map<_,_>>())},x=>x}}
fn hash(v:&Value)->String{Sha256::digest(serde_json::to_vec(v).unwrap_or_default()).iter().map(|b|format!("{b:02x}")).collect()}
fn vkey(v:&Value)->String{match v{Value::String(s)=>s.clone(),_=>v.to_string()}}
fn dtype(v:&Value)->&'static str{match v{Value::Null=>"null",Value::Bool(_)=>"boolean",Value::Number(n)=>if n.is_i64()||n.is_u64(){"integer"}else{"number"},Value::String(_)=>"string",Value::Array(_)=>"array",Value::Object(_)=>"object"}}
fn schema_ok(record:&Value,row:usize,r:&DataProcessRequest,issues:&mut Vec<DataIssue>)->bool{let mut ok=true;for field in &r.schema{match path_value(record,&field.path){None if field.required=>{issues.push(DataIssue{code:"SCHEMA_REQUIRED_MISSING",row,field:Some(field.path.clone()),detail:field.kind.clone()});ok=false},Some(Value::Null)if !field.nullable=>{issues.push(DataIssue{code:"SCHEMA_NULL_FORBIDDEN",row,field:Some(field.path.clone()),detail:field.kind.clone()});ok=false},Some(v)if dtype(v)!=field.kind&&!(field.kind=="number"&&dtype(v)=="integer")=>{issues.push(DataIssue{code:"SCHEMA_TYPE_MISMATCH",row,field:Some(field.path.clone()),detail:format!("expected={},actual={}",field.kind,dtype(v))});ok=false},_=>{}}}ok}
fn diff(base:&[Value],cur:&[Value])->DataDiff{let b:BTreeSet<_>=base.iter().map(hash).collect();let c:BTreeSet<_>=cur.iter().map(hash).collect();DataDiff{added:c.difference(&b).count(),removed:b.difference(&c).count(),unchanged:b.intersection(&c).count(),added_hashes:c.difference(&b).cloned().collect(),removed_hashes:b.difference(&c).cloned().collect()}}
pub fn process_json(source:&str)->Result<String,String>{let r:DataProcessRequest=serde_json::from_str(source).map_err(|e|format!("DATA_REQUEST_JSON:{e}"))?;if r.records.len()>1_000_000{return Err("DATA_RECORD_COUNT_LIMIT".into())}let estimated=source.len();let limit=if r.memory_limit_bytes==0{256*1024*1024}else{r.memory_limit_bytes};if estimated>limit{return Err("DATA_MEMORY_LIMIT_EXCEEDED".into())}let chunk=if r.chunk_size==0{10_000}else{r.chunk_size.min(100_000)};let mut issues=Vec::new();let mut seen=BTreeMap::<String,usize>::new();let mut out=Vec::new();let mut duplicates=0;let mut invalid=0;let mut cancelled=false;for(index,raw)in r.records.iter().cloned().enumerate(){if r.cancel_after_rows.map(|v|index>=v).unwrap_or(false){cancelled=true;break}let row=index+1;let value=normalize(raw,&r);if !value.is_object(){issues.push(DataIssue{code:"RECORD_NOT_OBJECT",row,field:None,detail:"object required".into()});invalid+=1;continue}let mut ok=schema_ok(&value,row,&r,&mut issues);for f in &r.required_fields{if path_value(&value,f).map(|v|v.is_null()||matches!(v,Value::String(s)if s.is_empty())).unwrap_or(true){issues.push(DataIssue{code:"REQUIRED_FIELD_MISSING",row,field:Some(f.clone()),detail:f.clone()});ok=false}}if !ok{invalid+=1;continue}let key=if r.dedupe_keys.is_empty(){hash(&value)}else{r.dedupe_keys.iter().map(|f|path_value(&value,f).map(vkey).unwrap_or_else(||"<missing>".into())).collect::<Vec<_>>().join("\u{1f}")};if let Some(position)=seen.get(&key).copied(){duplicates+=1;issues.push(DataIssue{code:"DUPLICATE_RECORD",row,field:None,detail:r.duplicate_policy.clone()});if r.duplicate_policy.eq_ignore_ascii_case("KEEP_LAST"){out[position]=value}continue}seen.insert(key,out.len());out.push(value)}let mut indexes=BTreeMap::new();for field in &r.index_fields{let mut map:BTreeMap<String,Vec<usize>>=BTreeMap::new();for(i,v)in out.iter().enumerate(){if let Some(x)=path_value(v,field){map.entry(vkey(x)).or_default().push(i)}}indexes.insert(field.clone(),map)}let mut sqlite_ready=true;if !r.sqlite_columns.is_empty(){for(i,v)in out.iter().enumerate(){if let Some(obj)=v.as_object(){for key in obj.keys(){if !r.sqlite_columns.contains(key){issues.push(DataIssue{code:"SQLITE_COLUMN_UNKNOWN",row:i+1,field:Some(key.clone()),detail:key.clone()});sqlite_ready=false}}}}}let baseline:Vec<Value>=r.baseline_records.iter().cloned().map(|v|normalize(v,&r)).collect();let changes=diff(&baseline,&out);let canonical=Value::Array(out.clone());let canonical_sha256=hash(&canonical);let schema_valid=!issues.iter().any(|i|i.code.starts_with("SCHEMA_")||i.code=="REQUIRED_FIELD_MISSING");let evidence=DataEvidence{contract_version:1,canonical_sha256:canonical_sha256.clone(),issue_count:issues.len(),schema_valid,sqlite_ready,processed_chunks:(out.len()+chunk-1)/chunk};let result=DataProcessResult{records:out,input_count:r.records.len(),output_count:canonical.as_array().map(Vec::len).unwrap_or(0),duplicate_count:duplicates,invalid_count:invalid,indexes,canonical_sha256,issues,diff:changes,evidence,estimated_bytes:estimated,cancelled,engine:"RUST",owner_domain:"data",receipt_version:2};serde_json::to_string(&result).map_err(|e|format!("DATA_RESULT_JSON:{e}"))}
